public class ThreadDemonstration {
    public static void main(String[] args) throws InterruptedException {
        Runnable task = () -> {
            String threadName = Thread.currentThread().getName();
            System.out.println("Executing concurrent work inside thread: " + threadName);
        };

        Thread worker1 = new Thread(task, "Worker-Thread-One");
        Thread worker2 = new Thread(task, "Worker-Thread-Two");

        worker1.start();
        worker2.start();

        worker1.join();
        worker2.join();
        System.out.println("All threads finished execution within the main process.");
    }
}
